import sqlparse
from sqlparse.sql import Function
p = sqlparse.parse(\"select some_function(a, b, c, d) as foo from t\")[0]
for tok in p.flatten():
    pass
def find(tl):
    for t in tl.tokens:
        if isinstance(t, Function):
            print('Function tokens:', [(type(x).__name__, repr(str(x))) for x in t.tokens])
        if t.is_group:
            find(t)
